import {describe, it, expect, jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry unit', () => {
  it('throws at registration time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    // This should fail once AJV is implemented and we pass an invalid schema
    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {
              age: {type: 'not-a-type'},
            },
          },
        },
        async () => 'result'
      )
    ).toThrow(/broken_tool/);
  });

  it('returns a ToolResponse naming missing required fields and does not call the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'test_tool',
        description: 'description',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
          required: ['foo'],
        },
      },
      executor
    );

    const response = await registry.execute('test_tool', {});

    expect(executor).not.toHaveBeenCalled();
    expect(response.result).toMatch(/foo/);
    expect(response.result).toMatch(/required/i);
  });

  it('caches compiled validators for dynamic schemas by schema object reference', async () => {
    const registry = new ToolRegistry();
    const schema = {
      type: 'object',
      properties: {foo: {type: 'string'}},
      required: ['foo'],
    };
    const executor = jest.fn(async () => 'ok');

    registry.register(() => ({
      name: 'dynamic_tool',
      description: 'desc',
      inputSchema: schema,
    }), executor);

    // First call: compiles and caches
    await registry.execute('dynamic_tool', {foo: 'bar'});
    expect(executor).toHaveBeenCalledTimes(1);

    // Second call with SAME schema object: should use cache
    await registry.execute('dynamic_tool', {foo: 'baz'});
    expect(executor).toHaveBeenCalledTimes(2);

    // Third call with DIFFERENT schema object (same content): should recompile
    const schema2 = {...schema};
    registry.register(() => ({
      name: 'dynamic_tool',
      description: 'desc',
      inputSchema: schema2,
    }), executor);

    await registry.execute('dynamic_tool', {foo: 'qux'});
    expect(executor).toHaveBeenCalledTimes(3);
  });
});

