private getDynamicValidator(definition: ToolDefinition): ValidateFunction {
  const schema = definition.inputSchema as Record<string, unknown>;
  let validator = validatorCache.get(schema);
  if (!validator) {
    validator = ajv.compile(schema);
    validatorCache.set(schema, validator);
  }
  return validator;
}

/** Validates input against the tool's inputSchema and invokes its executor. (See specs/hal-engine-tool-input-validation/spec.md) */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const definition = this.resolveDefinition(tool.definitionSource);
  const validator = tool.staticValidator ?? this.getDynamicValidator(definition);

  if (!validator(input)) {
    const errors = validator.errors || [];
    const result = `Validation failed for tool ${name}: ${errors
      .map(err => {
        const path = err.instancePath || (err.keyword === 'required' ? `.${err.params.missingProperty}` : '');
        return `${path} ${err.message}`;
      })
      .join(', ')}`;
    log.warn('tool', 'validation failed', {name, errorCount: errors.length});
    return {result};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);

